// Arma el aviso de Telegram con lo que hay que preparar.
//
// `items[].name` ya viene con la talla pegada —"Vestido Asimetría Floral - M"—
// que es justo lo que hace falta para coger la prenda de la estantería.
// `price.name` trae la talla suelta por si algún día se quiere en otra columna.

const pedido = $input.first().json;
const items = pedido.items || [];

const euros = (n) =>
  new Intl.NumberFormat('es-ES', { style: 'currency', currency: pedido.currency || 'EUR' }).format(n || 0);

const lineas = items.map((it) => {
  const talla = it.price && it.price.name ? it.price.name : null;
  // el nombre suele acabar en " - M": si ya lleva la talla, no se repite
  const nombre = it.name || (it.product && it.product.name) || 'Artículo';
  const yaLaLleva = talla && nombre.toLowerCase().endsWith('- ' + String(talla).toLowerCase());
  const cantidad = it.qty || it.quantity || 1;
  return '· ' + nombre + (talla && !yaLaLleva ? ' — talla ' + talla : '') + ' ×' + cantidad;
});

// Si el pedido llegara sin artículos, se avisa en vez de mandar un mensaje mudo:
// es preferible que Sara vea "no he podido leerlo" a que crea que no hay nada.
const cuerpo = lineas.length
  ? lineas.join('\n')
  : '⚠️ No he podido leer los artículos de este pedido. Míralo en Payments → Orders.';

const quien = [
  $('Webhook').first().json.body?.numero_pedido,
  pedido.contactSnapshot ? [pedido.contactSnapshot.firstName, pedido.contactSnapshot.lastName].filter(Boolean).join(' ') : null,
].filter(Boolean).join(' · ');

const mensaje = [
  'Pedido nuevo' + (quien ? ' ' + quien : ''),
  '',
  cuerpo,
  '',
  'Total ' + euros(pedido.amount),
].join('\n');

return [{ json: { mensaje, orderId: pedido._id, articulos: items.length } }];
